import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main4 {
    public static void main(String[] args) {
        InputStream input = System.in;
        OutputStream output = System.out;
        InputReader reader = new InputReader(input);
        PrintWriter writer = new PrintWriter(output);
        Solver processor = new Solver();
        processor.run(1, reader, writer);
        writer.close();
    }

    static class Solver {
        static final int N_MAX = 1 << 20;
        static double[] cosineArr = new double[N_MAX];
        static double[] sineArr = new double[N_MAX];
        static double[] negCosineArr = new double[N_MAX];
        static double[] negSineArr = new double[N_MAX];

        static {
            for (int groupSize = 1; groupSize <= cosineArr.length; groupSize <<= 1) {
                int mid = groupSize >> 1;
                for (int i = mid; i < groupSize; i++) {
                    double angle = 2 * Math.PI * (i - mid) / groupSize;
                    cosineArr[i] = Math.cos(angle);
                    sineArr[i] = Math.sin(angle);
                    negCosineArr[i] = Math.cos(-angle);
                    negSineArr[i] = Math.sin(-angle);
                }
            }
        }

        void run(int testNum, InputReader reader, PrintWriter writer) {
            final int MOD = 998244353;
            int n = reader.readInt();
            int k = reader.readInt();
            int[] vec = new int[10];
            for (int i = 0; i < k; i++) {
                int position = reader.readInt();
                vec[position] = 1;
            }

            int[] result = new int[]{1};
            int power = n / 2;

            while (true) {
                if ((power & 1) == 1) {
                    result = multiply(result, vec, MOD);
                }
                power >>= 1;
                if (power == 0) break;
                vec = multiply(vec, vec, MOD);
            }

            long total = 0;
            for (int val : result) {
                total += (long) val * val;
            }
            writer.println(total % MOD);
        }

        int[] multiply(int[] A, int[] B, int mod) {
            int neededLength = A.length + B.length - 1;
            int N = Math.max(2, Integer.highestOneBit(neededLength - 1) << 1);

            double[] realA = new double[N];
            double[] imagA = new double[N];
            for (int i = 0; i < A.length; i++) {
                int val = ((A[i] % mod) + mod) % mod;
                realA[i] = val & 0x7FFF;
                imagA[i] = val >>> 15;
            }
            fourierTransform(realA, imagA, false);

            double[] realB = new double[N];
            double[] imagB = new double[N];
            for (int i = 0; i < B.length; i++) {
                int val = ((B[i] % mod) + mod) % mod;
                realB[i] = val & 0x7FFF;
                imagB[i] = val >>> 15;
            }
            fourierTransform(realB, imagB, false);

            double[] resReal = new double[N];
            double[] resImag = new double[N];

            for (int i = 0; i < N; i++) {
                int j = (N - i) & (N - 1);
                double ar1 = (realA[i] + realA[j]) / 2;
                double ai1 = (imagA[i] - imagA[j]) / 2;
                double ar2 = (imagA[i] + imagA[j]) / 2;
                double ai2 = (realA[j] - realA[i]) / 2;

                double br1 = (realB[i] + realB[j]) / 2;
                double bi1 = (imagB[i] - imagB[j]) / 2;
                double br2 = (imagB[i] + imagB[j]) / 2;
                double bi2 = (realB[j] - realB[i]) / 2;

                resReal[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
                resImag[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
            }

            fourierTransform(resReal, resImag, true);
            int[] output = new int[neededLength];
            for (int i = 0; i < neededLength; i++) {
                long aa = Math.round(resReal[i]);
                long bb = Math.round(resImag[i]);
                long cc = Math.round(resImag[N - i]);
                output[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
            }
            return output;
        }

        void fourierTransform(double[] re, double[] im, boolean isInverse) {
            int n = re.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift) >>> shift;
                if (i < j) {
                    double temp = re[i];
                    re[i] = re[j];
                    re[j] = temp;
                    temp = im[i];
                    im[i] = im[j];
                    im[j] = temp;
                }
            }

            for (int length = 2; length <= n; length <<= 1) {
                int half = length >> 1;
                int step = cosineArr.length / length;

                for (int groupStart = 0; groupStart < n; groupStart += length) {
                    for (int pos = 0, w = 0; pos < half; pos++, w += step) {
                        double wReal = isInverse ? negCosineArr[half + pos] : cosineArr[half + pos];
                        double wImag = isInverse ? negSineArr[half + pos] : sineArr[half + pos];

                        int idx1 = groupStart + pos;
                        int idx2 = groupStart + pos + half;

                        double uRe = re[idx1];
                        double uIm = im[idx1];
                        double vRe = re[idx2] * wReal - im[idx2] * wImag;
                        double vIm = re[idx2] * wImag + im[idx2] * wReal;

                        re[idx1] = uRe + vRe;
                        im[idx1] = uIm + vIm;
                        re[idx2] = uRe - vRe;
                        im[idx2] = uIm - vIm;
                    }
                }
            }

            if (isInverse) {
                double invN = 1.0 / n;
                for (int i = 0; i < n; i++) {
                    re[i] *= invN;
                    im[i] *= invN;
                }
            }
        }
    }

    static class InputReader {
        final InputStream stream;
        final byte[] buffer = new byte[1024];
        int position = 0;
        int limit = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        int readInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return value * sign;
        }

        int read() {
            if (limit == -1) throw new InputMismatchException();
            if (position >= limit) {
                position = 0;
                try {
                    limit = stream.read(buffer);
                } catch (Exception e) {
                    throw new InputMismatchException();
                }
                if (limit <= 0) return -1;
            }
            return buffer[position++] & 0xFF;
        }

        static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
